using FluentAssertions;
using TCV.App.Settings;
using TCV.App.Shells;

namespace TCV.App.Tests;

/// <summary>
/// Which Windows Terminal profile is the command line's shell: the program decides, generated profiles
/// are known by their source, and the name only breaks a tie.
/// </summary>
public class WindowsTerminalProfilesTests
{
    // As Windows Terminal writes it: comments, trailing commas, generated profiles without a command line.
    private const string Settings = """
        {
            // This file was initially generated by Windows Terminal
            "defaultProfile": "{574e775e-4f2a-5b96-ac1e-a2962a402336}",
            "profiles":
            {
                "defaults": {},
                "list":
                [
                    { "commandline": "%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", "guid": "{61c54bbd-c2c6-5271-96e7-009a87ff44bf}", "hidden": false, "name": "Windows PowerShell" },
                    { "commandline": "%SystemRoot%\\System32\\cmd.exe", "guid": "{0caa0dad-35be-5f56-a8ff-afceeeaa6101}", "hidden": false, "name": "Command Prompt" },
                    { "guid": "{574e775e-4f2a-5b96-ac1e-a2962a402336}", "hidden": false, "name": "PowerShell", "source": "Windows.Terminal.PowershellCore" },
                    { "guid": "{2ece5bfe-50ed-5f3a-ab87-5cd4baafed2b}", "hidden": false, "name": "Git Bash", "source": "Git" },
                    { "guid": "{51855cb2-8cce-5362-8f54-464b92b32386}", "hidden": false, "name": "Ubuntu-24.04", "source": "Windows.Terminal.Wsl" },
                    { "guid": "{b453ae62-4e3d-5e58-b989-0a998ec441b8}", "hidden": true, "name": "Azure Cloud Shell", "source": "Windows.Terminal.Azure" },
                    { "commandline": "%SystemRoot%\\System32\\cmd.exe /k \"C:\\VS\\VsDevCmd.bat\"", "guid": "{11111111-0000-0000-0000-000000000000}", "name": "Developer Command Prompt" },
                ],
            },
        }
        """;

    private static readonly IReadOnlyList<WindowsTerminalProfile> Profiles = WindowsTerminalProfiles.Parse(Settings);

    private static ShellProfile Shell(string name, string command, string arguments = "%C") =>
        new() { Name = name, Command = command, Arguments = arguments };

    private static ShellProfile FromCatalog(string name) =>
        ShellCatalog.All.Single(s => s.Name == name) is var t ? t.ToSettings(t.Command.Length > 0 ? t.Command : t.ProbePaths[0]) : null!;

    [Fact]
    public void Parse_ReadsTheFileAsWindowsTerminalWritesIt()
    {
        Profiles.Should().HaveCount(7);
        Profiles[2].Should().Be(new WindowsTerminalProfile(
            "PowerShell", "{574e775e-4f2a-5b96-ac1e-a2962a402336}", "Windows.Terminal.PowershellCore", null, false));
        Profiles[5].Hidden.Should().BeTrue();
    }

    [Fact]
    public void Parse_TheProfilesAsAPlainList_AreReadToo()
    {
        WindowsTerminalProfiles.Parse("""{ "profiles": [ { "name": "cmd", "commandline": "cmd.exe" } ] }""")
            .Should().ContainSingle().Which.Commandline.Should().Be("cmd.exe");
    }

    [Theory]
    [InlineData("")]
    [InlineData("not json")]
    [InlineData("[]")]
    [InlineData("""{ "profiles": 5 }""")]
    [InlineData("""{ "profiles": [ { "guid": "{x}" }, 7 ] }""")]
    public void Parse_AFileThatDoesNotRead_HasNoProfiles(string json)
    {
        WindowsTerminalProfiles.Parse(json).Should().BeEmpty();
    }

    [Theory]
    [InlineData("cmd", "Command Prompt")]
    [InlineData("Windows PowerShell", "Windows PowerShell")]
    [InlineData("PowerShell 7", "PowerShell")]
    [InlineData("Git Bash", "Git Bash")]
    public void Match_EveryCatalogShell_FindsTheProfileWindowsTerminalMadeForIt(string shell, string profile)
    {
        WindowsTerminalProfiles.Match(FromCatalog(shell), Profiles)!.Name.Should().Be(profile);
    }

    [Fact]
    public void Match_AWslDistribution_IsItsOwnProfile()
    {
        var ubuntu = ShellCatalog.ForWslDistribution(ShellCatalog.WslProgram, "Ubuntu-24.04");
        var debian = ShellCatalog.ForWslDistribution(ShellCatalog.WslProgram, "Debian");

        WindowsTerminalProfiles.Match(ubuntu, Profiles)!.Name.Should().Be("Ubuntu-24.04");
        WindowsTerminalProfiles.Match(debian, Profiles).Should().BeNull();
    }

    [Fact]
    public void Match_WslBash_IsNotGitBash()
    {
        WindowsTerminalProfiles.Match(Shell("bash", @"C:\Windows\System32\bash.exe"), Profiles).Should().BeNull();
        WindowsTerminalProfiles.Match(Shell("bash", "bash"), Profiles).Should().BeNull();
    }

    [Fact]
    public void Match_AProfileWithArgumentsOfItsOwn_StandsForTheShellOnlyUnderItsName()
    {
        var profiles = Profiles.Where(p => p.Name != "Command Prompt").ToList();

        WindowsTerminalProfiles.Match(Shell("cmd", "cmd.exe"), profiles).Should().BeNull();
        WindowsTerminalProfiles.Match(Shell("Developer Command Prompt", "cmd.exe"), profiles)!.Name
            .Should().Be("Developer Command Prompt");
    }

    [Fact]
    public void Match_TheProfileNamedAsTheShell_WinsATie()
    {
        IReadOnlyList<WindowsTerminalProfile> profiles =
        [
            new("Command Prompt", "{a}", null, "cmd.exe", false),
            new("cmd", "{b}", null, "cmd.exe", false),
        ];

        WindowsTerminalProfiles.Match(Shell("CMD ", "cmd.exe"), profiles)!.Guid.Should().Be("{b}");
    }

    [Fact]
    public void Match_AHiddenProfile_IsNotOffered()
    {
        IReadOnlyList<WindowsTerminalProfile> profiles = [new("cmd", "{a}", null, "cmd.exe", true)];

        WindowsTerminalProfiles.Match(Shell("cmd", "cmd.exe"), profiles).Should().BeNull();
    }

    [Fact]
    public void Match_TwoPaths_MustBeTheSamePath()
    {
        IReadOnlyList<WindowsTerminalProfile> profiles =
            [new("PowerShell Preview", "{p}", null, @"C:\Program Files\PowerShell\7-preview\pwsh.exe", false)];

        WindowsTerminalProfiles.Match(Shell("PowerShell 7", @"C:\Program Files\PowerShell\7\pwsh.exe"), profiles)
            .Should().BeNull();
        WindowsTerminalProfiles.Match(Shell("PowerShell 7", "pwsh.exe"), profiles)!.Guid.Should().Be("{p}");
    }

    [Theory]
    [InlineData(@"C:\Program Files\PowerShell\7\pwsh.exe")]
    [InlineData(@"""C:\Program Files\PowerShell\7\pwsh.exe""")]
    [InlineData(@"C:\Program Files\PowerShell\7\pwsh.exe -nologo")]
    public void Match_APathWithBlanks_IsReadQuotedOrNot(string commandline)
    {
        IReadOnlyList<WindowsTerminalProfile> profiles = [new("PowerShell 7", "{p}", null, commandline, false)];

        WindowsTerminalProfiles.Match(Shell("PowerShell 7", @"C:\Program Files\PowerShell\7\pwsh.exe"), profiles)!
            .Guid.Should().Be("{p}");
    }

    [Fact]
    public void Match_AShellNoProfileRuns_HasNone()
    {
        WindowsTerminalProfiles.Match(Shell("Nushell", "nu.exe"), Profiles).Should().BeNull();
        WindowsTerminalProfiles.Match(Shell("empty", "  "), Profiles).Should().BeNull();
    }

    [Fact]
    public void Selector_IsTheGuid_ElseTheName()
    {
        WindowsTerminalProfiles.Selector(new("cmd", "{a}", null, null, false)).Should().Be("{a}");
        WindowsTerminalProfiles.Selector(new("My cmd", null, null, null, false)).Should().Be("My cmd");
    }

    // ── wt.exe's arguments ────────────────────────────────────────────────────

    [Fact]
    public void ForWindowsTerminalProfile_OpensTheProfileItself_InTheFolder()
    {
        ShellCommandLine.ForWindowsTerminalProfile("{a}", @"D:\").Should().Be(@"-p ""{a}"" -d ""D:\\""");
        ShellCommandLine.ForWindowsTerminalProfile(null, @"D:\x").Should().Be(@"-d ""D:\x""");
        ShellCommandLine.ForWindowsTerminalProfile("Mine; yours", @"D:\x").Should().Be(@"-p ""Mine\; yours"" -d ""D:\x""");
        ShellCommandLine.ForWindowsTerminalProfile(null, @"D:\a;b").Should().Be(@"-d ""D:\a\;b""");
    }

    [Fact]
    public void ForWindowsTerminal_WithAProfile_RunsTheCommandInItsLooks()
    {
        var launch = ShellCommandLine.Build("cmd.exe", "/s /k %C", "dir", @"D:\x");

        ShellCommandLine.ForWindowsTerminal(launch, @"D:\x", "{a}").Should()
            .Be("-p \"{a}\" " + ShellCommandLine.ForWindowsTerminal(launch, @"D:\x"));
    }
}
